// Runs your solution and writes its results to output/.
//
// DO NOT EDIT THIS FILE. The marking harness replaces it with its own copy and
// runs it on the data you were given and on a second, unseen track.
//
//     ./cpp/build/runner 1      # Task 1  -> output/cones.csv
//     ./cpp/build/runner 2a     # Task 2a -> output/racing_line.csv
//     ./cpp/build/runner 2b     # Task 2b -> output/projections.csv
//     ./cpp/build/runner all    # every task you have implemented
//
// Options: --data DIR (default data/), --out DIR (default output/)
#include <chrono>
#include <cmath>
#include <cstdio>
#include <filesystem>
#include <fstream>
#include <functional>
#include <iostream>
#include <set>
#include <sstream>
#include <string>
#include <vector>

#include "challenge.hpp"
#include "challenge_io.hpp"

namespace fs = std::filesystem;

namespace {

struct InterfaceError : std::runtime_error {
    using std::runtime_error::runtime_error;
};

void check_finite(double v, const std::string& what) {
    if (!std::isfinite(v)) throw InterfaceError(what + " is not a finite number");
}

// The runner's own cone reader, so Tasks 2a/2b are marked independently of Task 1.
std::vector<Cone> read_cones(const std::string& path) {
    std::vector<Cone> cones;
    for (const auto& r : challenge_io::read_csv_rows(path)) {
        cones.push_back(Cone{r.at(0), std::stod(r.at(1)), std::stod(r.at(2))});
    }
    return cones;
}

std::ofstream open_out(const std::string& dir, const std::string& name) {
    fs::create_directories(dir);
    std::ofstream f(dir + "/" + name);
    if (!f) throw std::runtime_error("cannot write " + dir + "/" + name);
    f.setf(std::ios::fixed);
    return f;
}

std::string task_1(const std::string& data, const std::string& out) {
    const auto cones = parse_cones(data + "/track.csv");
    auto f = open_out(out, "cones.csv");
    f.precision(6);
    f << "side,x,y\n";
    for (std::size_t i = 0; i < cones.size(); ++i) {
        check_finite(cones[i].x, "cone " + std::to_string(i) + " x");
        check_finite(cones[i].y, "cone " + std::to_string(i) + " y");
        f << cones[i].side << ',' << cones[i].x << ',' << cones[i].y << '\n';
    }
    return std::to_string(cones.size()) + " cones";
}

std::string task_2a(const std::string& data, const std::string& out) {
    const auto line = plan_racing_line(read_cones(data + "/track.csv"));
    if (line.size() < 3) throw InterfaceError("racing line has only " + std::to_string(line.size()) + " points");
    auto f = open_out(out, "racing_line.csv");
    f.precision(6);
    f << "x,y\n";
    for (std::size_t i = 0; i < line.size(); ++i) {
        check_finite(line[i].x, "point " + std::to_string(i) + " x");
        check_finite(line[i].y, "point " + std::to_string(i) + " y");
        f << line[i].x << ',' << line[i].y << '\n';
    }
    return std::to_string(line.size()) + " points";
}

std::string task_2b(const std::string& data, const std::string& out) {
    const auto cones = read_cones(data + "/track.csv");
    const auto camera = challenge_io::load_camera(data + "/camera.json");
    const auto trajectory = challenge_io::load_trajectory(data + "/trajectory.csv");
    std::ostringstream rows;
    rows.setf(std::ios::fixed);
    rows.precision(3);
    std::size_t n = 0;
    for (auto t : challenge_io::load_frames(data + "/frames.csv")) {
        const auto result = project_cones(cones, trajectory.at(t), camera);
        for (const auto& p : result) {
            if (p.cone_index < 0 || p.cone_index >= static_cast<int>(cones.size()))
                throw InterfaceError("frame " + std::to_string(t) + ": cone_index " +
                                     std::to_string(p.cone_index) + " is not a valid index");
            check_finite(p.u, "u");
            check_finite(p.v, "v");
            rows << t << ',' << p.cone_index << ',' << p.u << ',' << p.v << '\n';
            ++n;
        }
    }
    auto f = open_out(out, "projections.csv");
    f << "timestamp_ms,cone_index,u,v\n" << rows.str();
    return std::to_string(n) + " projections";
}

}  // namespace

int main(int argc, char** argv) {
    std::string task, data = challenge_io::kDataDir, out = challenge_io::kOutputDir;
    for (int i = 1; i < argc; ++i) {
        std::string a = argv[i];
        if (a == "--data" && i + 1 < argc) data = argv[++i];
        else if (a == "--out" && i + 1 < argc) out = argv[++i];
        else task = a;
    }
    const std::vector<std::pair<std::string, std::function<std::string(const std::string&, const std::string&)>>> tasks = {
        {"1", task_1}, {"2a", task_2a}, {"2b", task_2b}};
    if (task != "1" && task != "2a" && task != "2b" && task != "all") {
        std::cerr << "usage: runner {1|2a|2b|all} [--data DIR] [--out DIR]\n";
        return 2;
    }
    std::set<std::string> status;
    for (const auto& [name, fn] : tasks) {
        if (task != "all" && task != name) continue;
        const auto start = std::chrono::steady_clock::now();
        try {
            const auto msg = fn(data, out);
            const double s = std::chrono::duration<double>(std::chrono::steady_clock::now() - start).count();
            std::printf("Task %s: ok, %s (%.2f s)\n", name.c_str(), msg.c_str(), s);
            status.insert("ok");
        } catch (const NotImplemented&) {
            std::printf("Task %s: not implemented\n", name.c_str());
            status.insert("not implemented");
        } catch (const InterfaceError& e) {
            std::printf("Task %s: INTERFACE ERROR: %s\n", name.c_str(), e.what());
            status.insert("interface error");
        } catch (const std::exception& e) {
            std::printf("Task %s: CRASHED: %s\n", name.c_str(), e.what());
            status.insert("crashed");
        } catch (...) {
            std::printf("Task %s: CRASHED\n", name.c_str());
            status.insert("crashed");
        }
        std::fflush(stdout);
    }
    const bool bad = status.count("crashed") || status.count("interface error") ||
                     (task != "all" && status.count("not implemented"));
    return bad ? 1 : 0;
}
